import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Strategy — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"strategy-01-overview-and-concepts.md","filePath":"strategy-01-overview-and-concepts.md"}'),n={name:"strategy-01-overview-and-concepts.md"};function i(s,t,h,l,d,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="strategy-—-overview-concepts" tabindex="-1">Strategy — Overview &amp; Concepts <a class="header-anchor" href="#strategy-—-overview-concepts" aria-label="Permalink to &quot;Strategy — Overview &amp; Concepts&quot;">​</a></h1><p><em>What it is, why it matters, and how it fits into Lodestone</em></p><hr><h2 id="what-is-a-strategy" tabindex="-1">What Is a Strategy? <a class="header-anchor" href="#what-is-a-strategy" aria-label="Permalink to &quot;What Is a Strategy?&quot;">​</a></h2><p>In Lodestone, a Strategy is a long-term plan that explicitly defines where your organization is headed, how it intends to get there, and what tradeoffs it is willing to make over time.</p><p>Lodestone treats Strategy as a <strong>route</strong>, not a wish. The distinction matters:</p><table tabindex="0"><thead><tr><th></th><th>Example</th></tr></thead><tbody><tr><td>Vision</td><td>I&#39;d like to visit Paris someday</td></tr><tr><td>Mission</td><td>I will visit Paris this fall</td></tr><tr><td>Objective</td><td>Be in Paris in early October</td></tr><tr><td><strong>Strategy</strong></td><td>Fly from Toronto, stop in London, then continue to Paris</td></tr><tr><td>Tactics</td><td>Book flights, hotels, transportation</td></tr></tbody></table><p>Lodestone&#39;s Strategy module lives in the route-definition layer. It&#39;s not about aspirations — it&#39;s about the explicit path and tradeoffs required to get somewhere.</p><hr><h2 id="why-strategy-exists-in-lodestone" tabindex="-1">Why Strategy Exists in Lodestone <a class="header-anchor" href="#why-strategy-exists-in-lodestone" aria-label="Permalink to &quot;Why Strategy Exists in Lodestone&quot;">​</a></h2><p>Strategy is one of the hardest things for product teams to articulate clearly. Most attempts produce either vague mission statements (&quot;delight customers&quot;) or lists of goals that don&#39;t actually force any choices.</p><p>Lodestone&#39;s Strategy module exists to fix this by:</p><ul><li>Making it easy to spin up a first strategic position quickly</li><li>Forcing explicit tradeoffs through constrained structure</li><li>Encouraging sharing and iteration early, rather than waiting for perfection</li></ul><p>Strategy in Lodestone is a starting point for discussion, not a final decree handed down from above.</p><hr><h2 id="the-planning-stack-cadence" tabindex="-1">The Planning Stack Cadence <a class="header-anchor" href="#the-planning-stack-cadence" aria-label="Permalink to &quot;The Planning Stack Cadence&quot;">​</a></h2><p>Strategy sits at the longest time horizon in Lodestone&#39;s planning stack:</p><table tabindex="0"><thead><tr><th>Module</th><th>Thinks in...</th></tr></thead><tbody><tr><td>Releases</td><td>Weeks</td></tr><tr><td>Roadmaps</td><td>Months</td></tr><tr><td><strong>Strategy</strong></td><td><strong>Years</strong></td></tr></tbody></table><p>A Strategy typically spans multiple years. Users define both the total length and the time interval — monthly, quarterly, or annually. A three-year strategy with quarterly intervals produces 12 intervals.</p><hr><h2 id="the-growth-cube" tabindex="-1">The Growth Cube <a class="header-anchor" href="#the-growth-cube" aria-label="Permalink to &quot;The Growth Cube&quot;">​</a></h2><p>Strategies are visualized using a <strong>growth cube</strong> — an animated 3D representation that shows how investment allocation shifts across your three strategic dimensions over time.</p><p>Each frame of the animation represents one time interval. The cube can play through automatically or be stepped through manually, making it easy to walk an audience through the strategic arc of your plan — how you&#39;re investing early, where you shift emphasis over time, and what tradeoffs you&#39;re making at each stage.</p><hr><h2 id="strategy-as-a-table" tabindex="-1">Strategy as a Table <a class="header-anchor" href="#strategy-as-a-table" aria-label="Permalink to &quot;Strategy as a Table&quot;">​</a></h2><p>Under the hood, every Strategy is a table with:</p><ul><li>Exactly <strong>3 columns</strong> — one for each strategic investment dimension</li><li>A user-defined number of <strong>rows</strong> — one for each time interval</li></ul><p>The table drives the growth cube visualization. As you fill in values, the cube updates to reflect your investment allocation across dimensions and over time.</p><hr><h2 id="the-three-dimensions" tabindex="-1">The Three Dimensions <a class="header-anchor" href="#the-three-dimensions" aria-label="Permalink to &quot;The Three Dimensions&quot;">​</a></h2><p>The three columns represent your strategic investment dimensions — the areas where you&#39;re making deliberate allocation decisions. The default dimensions are:</p><ul><li>Products and Services</li><li>Customer Segmentation</li><li>Geographic Expansion</li></ul><p>These can be renamed to anything that fits your organization. Common alternatives include:</p><ul><li>Integrations / Self-Service / Enterprise</li><li>New Markets / Retention / Platform</li><li>Core Product / Ecosystem / Infrastructure</li></ul><p>The <strong>constraint of exactly three dimensions is intentional</strong>. It forces meaningful tradeoffs. With unlimited dimensions, everything can be a priority — and when everything is a priority, nothing is.</p><hr><h2 id="two-approaches-top-down-and-bottom-up" tabindex="-1">Two Approaches: Top-Down and Bottom-Up <a class="header-anchor" href="#two-approaches-top-down-and-bottom-up" aria-label="Permalink to &quot;Two Approaches: Top-Down and Bottom-Up&quot;">​</a></h2><p>Lodestone supports two fundamentally different ways of building a Strategy. The approach is chosen at creation and cannot be changed afterward.</p><h3 id="top-down" tabindex="-1">Top-Down <a class="header-anchor" href="#top-down" aria-label="Permalink to &quot;Top-Down&quot;">​</a></h3><p>Values are entered manually as plain numbers representing relative emphasis. No unit is enforced — the numbers are directional signals, not precise resource allocations. Top-down is favored when the goal is alignment on direction rather than grounding in execution detail.</p><h3 id="bottom-up" tabindex="-1">Bottom-Up <a class="header-anchor" href="#bottom-up" aria-label="Permalink to &quot;Bottom-Up&quot;">​</a></h3><p>Strategy dimensions are mapped to Feature tags. Each table cell is populated by selecting Features that match that tag, and their evaluation scores (value or effort) roll up into the cell value. Bottom-up is favored when you want to ground strategy in the actual work your team is planning.</p><p>Both types can coexist — a workspace can have multiple Strategies simultaneously, and you can create one of each type.</p><hr><h2 id="what-strategy-is-not" tabindex="-1">What Strategy Is Not <a class="header-anchor" href="#what-strategy-is-not" aria-label="Permalink to &quot;What Strategy Is Not&quot;">​</a></h2><ul><li><strong>Not a goals list.</strong> A list of things you want to achieve is not a strategy. Strategy is about the route and the tradeoffs — what you&#39;re choosing to do and what you&#39;re consciously choosing not to do.</li><li><strong>Not a roadmap.</strong> Roadmaps answer WHAT and WHY for near-to-medium term plans. Strategy answers WHERE and HOW MUCH across years.</li><li><strong>Not a final document.</strong> Lodestone actively encourages sharing early drafts and iterating. An imperfect strategy that&#39;s discussed is more valuable than a perfect one that never gets shared.</li></ul><hr><h2 id="who-can-create-strategies" tabindex="-1">Who Can Create Strategies <a class="header-anchor" href="#who-can-create-strategies" aria-label="Permalink to &quot;Who Can Create Strategies&quot;">​</a></h2><p>Any workspace member can create a Strategy — it is not restricted to admins. A workspace can have multiple Strategies simultaneously.</p><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for creating, editing, and exporting Strategies.</em></p>',51)])])}const g=e(n,[["render",i]]);export{u as __pageData,g as default};
